def solve(n):
    ans=[]
    def dfs(path):
        if len(path)==n: ans.append(path[:]); return
        for i in range(n):
            if i in path: continue
            path.append(i); dfs(path); path.pop()
    dfs([])
    return ans

def solve(n):
    ans=[]; path=[]
    def dfs(start):
        ans.append(path[:])
        for i in range(start,n):
            path.append(i); dfs(i+1); path.pop()
    dfs(0)
    return ans
